public int sumOfLeftLeaves(TreeNode root) {
    Map<TreeNode, TreeNode> parent = new HashMap<>();
    List<TreeNode> nodes = new ArrayList<>();
    Deque<TreeNode> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {              // record every node's parent
        TreeNode node = stack.pop();
        nodes.add(node);
        for (TreeNode child : new TreeNode[]{node.left, node.right}) {
            if (child != null) {
                parent.put(child, node);
                stack.push(child);
            }
        }
    }
    int sum = 0;
    for (TreeNode node : nodes) {
        boolean isLeaf = node.left == null && node.right == null;
        if (isLeaf && parent.containsKey(node) && parent.get(node).left == node) sum += node.val;
    }
    return sum;
}

int sumOfLeftLeaves(TreeNode* root) {
    unordered_map<TreeNode*, TreeNode*> parent;
    vector<TreeNode*> nodes;
    stack<TreeNode*> st;
    st.push(root);
    while (!st.empty()) {                   // record every node's parent
        TreeNode* node = st.top();
        st.pop();
        nodes.push_back(node);
        for (TreeNode* child : {node->left, node->right}) {
            if (child) {
                parent[child] = node;
                st.push(child);
            }
        }
    }
    int sum = 0;
    for (TreeNode* node : nodes) {
        bool isLeaf = !node->left && !node->right;
        if (isLeaf && parent.count(node) && parent[node]->left == node) sum += node->val;
    }
    return sum;
}

